export default {
    name: 'c_txt_tab',
    props: {
        name: {
            type: String
        },
        configData:{
            type:null
        }
    },
    data () {
        return {
            defaults: {},
            datas: this.configData
        }
    },
    mounted () {},
    watch: {
        configData: {
            handler (nVal, oVal) {
                this.datas = nVal
            },
            immediate: true,
            deep: true
        }
    },
    methods: {
        radioChange (e) {
            this.$emit('getConfig', { name: 'radio', values: e })
        }
    }
}
